package com.franco.desco.adapter.out.sqlserver.campaignparticipant;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.campaignparticipant.*;import com.franco.desco.application.campaignparticipant.port.out.CampaignParticipantPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.campaignparticipant.CampaignParticipantModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class CampaignParticipantSqlServerAdapter implements CampaignParticipantPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,include,program,remove;public CampaignParticipantSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("comercial","PA_ParticipacionCampaniaSocio_Sel_Listado","items");get=f.callWithResultSets("comercial","PA_ParticipacionCampaniaSocio_Sel_Detalle","header","operations","deliveries");include=f.call("comercial","PA_ParticipacionCampaniaSocio_Ins_Incluir");program=f.call("comercial","PA_ParticipacionCampaniaSocio_Ins_ProgramarOperativo");remove=f.call("comercial","PA_ParticipacionCampaniaSocio_Upd_Retirar");}
 public PersistenceResult<PageResult<CampaignParticipantModels.Summary>>list(CampaignParticipantCommands.ListParticipants c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var out=e.executeJson(list,pf.forQuery(i,m,map("filtros",map("campaniaVentaId",f==null?null:f.campaniaVentaId(),"estadoParticipacion",f==null?null:f.estadoParticipacion()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio()))));return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar los participantes.");}
 public PersistenceResult<CampaignParticipantModels.Detail>get(CampaignParticipantCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("participacion",Map.of("participacionId",c.participacionId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar el participante."));var h=one(out,"header");if(h==null)return PersistenceResult.error("El participante seleccionado no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Participante consultado correctamente."),new CampaignParticipantModels.Detail(SqlValues.longValue(h,"participacionId"),SqlValues.string(h,"estadoParticipacion"),SqlValues.instant(h,"fechaRegistro"),SqlValues.longValue(h,"campaniaVentaId"),SqlValues.string(h,"campania"),SqlValues.longValue(h,"socioId"),SqlValues.string(h,"numeroDocumento"),SqlValues.string(h,"socioNombre"),rows(out,"operations").stream().map(this::operation).toList(),rows(out,"deliveries").stream().map(this::delivery).toList()));}
 public PersistenceResult<Long>include(CampaignParticipantCommands.Include c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(include,pf.forWrite(i,m,c,Map.of("participacion",map("campaniaVentaId",c.campaniaVentaId(),"socioAsociacionId",c.socioAsociacionId()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nParticipacionId"),"No se pudo incluir al socio.");}public PersistenceResult<Long>program(CampaignParticipantCommands.Program c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(program,pf.forWrite(i,m,c,Map.of("programacion",map("participacionId",c.participacionId(),"operativoVentaId",c.operativoVentaId()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nOperativoSocioId"),"No se pudo programar al socio.");}public PersistenceResult<Void>remove(CampaignParticipantCommands.Remove c,SessionIdentity i,RequestMetadata m){return PaAdapterSupport.result(e.executeJson(remove,pf.forWrite(i,m,c,Map.of("participacion",map("participacionId",c.participacionId(),"motivo",c.motivo())))),null,"No se pudo retirar al socio.");}
 private CampaignParticipantModels.Summary summary(Map<String,Object>r){return new CampaignParticipantModels.Summary(SqlValues.longValue(r,"participacionId"),SqlValues.longValue(r,"campaniaVentaId"),SqlValues.string(r,"estadoParticipacion"),SqlValues.instant(r,"fechaRegistro"),SqlValues.longValue(r,"socioId"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"socioNombre"),SqlValues.longValue(r,"operativos"),SqlValues.longValue(r,"entregasConfirmadas"));}private CampaignParticipantModels.Operation operation(Map<String,Object>r){return new CampaignParticipantModels.Operation(SqlValues.longValue(r,"operativoSocioId"),SqlValues.longValue(r,"operativoVentaId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"estadoOperativo"),SqlValues.string(r,"estadoParticipacion"));}private CampaignParticipantModels.Delivery delivery(Map<String,Object>r){return new CampaignParticipantModels.Delivery(SqlValues.longValue(r,"entregaSocioId"),SqlValues.string(r,"codigoLote"),SqlValues.instant(r,"fechaHora"),SqlValues.decimal(r,"pesoAceptadoKg"),SqlValues.string(r,"estadoControlCalidad"),SqlValues.string(r,"estadoProceso"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
